    star (U * A * star U) = U * A * star U ∧ (U * A * star U).trace = 0

lemma eq_sum_gellMannCoeff_smul {M : Matrix (Fin 3) (Fin 3) ℂ}
    (hself : star M = M) (htr : M.trace = 0) :
